      "weight": 0.15,
      "depends_on": [2, 3]
    },
    {
      "id": 5,
      "claim": "Large‑scale epidemiological studies and systematic reviews find no association between regular coffee/caffeine intake and reduced height or growth velocity in children or adolescents.",
      "evidence": "American Academy of Pediatrics statements, longitudinal cohort data (e.g., Journal of Pediatric Endocrinology & Metabolism), and meta‑analyses.",
      "weight": 0.20,
      "depends_on": []
    },
